    int i() throws Exception { return Integer.parseInt(next()); }
    long l() throws Exception { return Long.parseLong(next()); }
  }
  public static void main(String[] args) throws Exception {
    Fast f = new Fast();
int n=f.i(),k=f.i();long[]a=new long[n];ArrayDeque<Integer>q=new ArrayDeque<>();StringBuilder s=new StringBuilder();for(int i=0;i<n;i++){a[i]=f.l();while(!q.isEmpty()&&q.peekFirst()<=i-k)q.removeFirst();while(!q.isEmpty()&&a[q.peekLast()]<=a[i])q.removeLast();q.addLast(i);if(i>=k-1)s.append(a[q.peekFirst()]).append(" ");}System.out.println(s);
